sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    var book_request_id = current.getValue('sysapproval');
    var approval_sysId = current.getValue('sys_id');

	if(current.group != 'e9f3ff367b475210d7260a89518cb6bc'){
		return;
	}
    var bookReqGR = new GlideRecord('sn_lms_book_requests');
    bookReqGR.addQuery('sys_id', book_request_id);
    bookReqGR.query();
    if (bookReqGR.next()) {
		console.log("-----in approvals----");
        var requestedDate = new GlideDateTime(bookReqGR.requested_date);
        var returnDate = new GlideDateTime(bookReqGR.return_date);

        // Add 15 days to the requested date
        requestedDate.addDaysUTC(15);
		console.log("-----in approvals----request date ----", requestedDate);
		console.log("-----in approvals----return date----", returnDate);
        if (returnDate <= requestedDate) {
            var approveGR = new GlideRecord('sysapproval_approver');
            approveGR.addQuery('sys_id', approval_sysId);
            approveGR.query();
            if (approveGR.next()) {
                approveGR.state = 'approved';
                approveGR.update();
            }
        }
    }



})(current, previous);
